"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2018],{19259:e=>{e.exports=JSON.parse('{"functions":[{"name":"demolish","desc":"Destroys queued chunk contents until the frame\'s shared deadline. Runs in\\n`Phases.PreUpdate`, alongside `hide` \u2014 teardown gets first claim on the\\nframe because it is what makes the next frame cheaper.\\n\\nRuns unconditionally rather than behind `resyncNeeded`: a teardown backlog\\nhas to keep draining whether or not anyone is moving.","params":[{"name":"world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":33,"path":"src/main/server/systems/maze/demolish.luau"}}],"properties":[],"types":[],"name":"demolish","desc":"Destroys unloaded chunks a child at a time.\\n\\nThis used to be a call at the bottom of `builder.step`. It is a system so the\\nordering is visible in the phase list rather than buried inside another\\nstage.","tags":["server-system"],"realm":["Server"],"source":{"line":12,"path":"src/main/server/systems/maze/demolish.luau"}}')}}]);